function 挂样式(): void {
  if (document.getElementById(`${前缀}-style`)) return;
  const 标签 = document.createElement('style');
  标签.id = `${前缀}-style`;
  标签.textContent = 样式;
  document.head.appendChild(标签);
}

function 建悬浮窗(): { 启动钮: HTMLElement; 窗口: HTMLElement; 列表: HTMLElement; 输入区: HTMLElement } {
  const 启动钮 = document.createElement('div');
  启动钮.id = `${前缀}-launcher`;
  启动钮.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 6 h4"/><path d="M12 18.5 v0.01"/></svg><span>手机</span>`;

  const 窗口 = document.createElement('div');
  窗口.id = `${前缀}-win`;
  窗口.innerHTML = `
    <div class="${前缀}__top">
      <div class="${前缀}__who"><span class="${前缀}__name">梵·醺儿</span><span class="${前缀}__state"></span></div>
      <button class="${前缀}__close" type="button">收起</button>
    </div>
    <div class="${前缀}__screen"></div>
    <div class="${前缀}__input">
      <input class="${前缀}__text" type="text" maxlength="200" placeholder="给梵·醺儿发消息" />
      <button class="${前缀}__send" type="button">发送</button>
    </div>`;

  document.body.appendChild(启动钮);
  document.body.appendChild(窗口);
  return {
    启动钮,
    窗口,
    列表: 窗口.querySelector(`.${前缀}__screen`) as HTMLElement,
    输入区: 窗口.querySelector(`.${前缀}__input`) as HTMLElement,
  };
}

function 时刻(ts: number): string {
  const d = new Date(ts);
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

$(() => {
  try {
    if (!是本卡()) return;
    挂样式();
    const { 启动钮, 窗口, 列表, 输入区 } = 建悬浮窗();
    const 按钮 = 窗口.querySelector(`.${前缀}__close`) as HTMLButtonElement;
    const 状态行 = 窗口.querySelector(`.${前缀}__state`) as HTMLElement;
    const 输入 = 窗口.querySelector(`.${前缀}__text`) as HTMLInputElement;
    const 发送钮 = 窗口.querySelector(`.${前缀}__send`) as HTMLButtonElement;

    let 记录: 手机短信[] = 读记录();
    let 发送中 = false;
    let 失败 = false;

    const 对局中 = (): boolean => 读对局状态() === '对局中';

    function 滚到底(): void {
      列表.scrollTop = 列表.scrollHeight;
    }

    function 渲染(): void {
      const 锁 = 对局中();
      状态行.textContent = 锁 ? '在牌桌上，没看手机' : '在线';
      输入区.style.display = 锁 ? 'none' : 'flex';
      启动钮.classList.toggle(`${前缀}--busy`, false);
      let 旧锁 = 窗口.querySelector(`.${前缀}__locked`);
      if (锁 && !旧锁) {
        旧锁 = document.createElement('div');
        旧锁.className = `${前缀}__locked`;
        旧锁.textContent = '对局进行中，她没在看手机。';
        窗口.appendChild(旧锁);
      } else if (!锁 && 旧锁) {
        旧锁.remove();
      }

      列表.textContent = '';
      if (记录.length === 0 && !发送中) {
        const 空 = document.createElement('div');
        空.className = `${前缀}__empty`;
        空.textContent = '还没有消息。给她发一条试试。';
        列表.appendChild(空);
      }
      for (const m of 记录) {
        const 条 = document.createElement('div');
        条.className = `${前缀}__sms ${m.我方 ? `${前缀}__sms--me` : `${前缀}__sms--her`}`;
        const 泡 = document.createElement('div');
        泡.className = `${前缀}__bubble`;
        泡.textContent = m.文;
        const 时 = document.createElement('span');
        时.className = `${前缀}__time`;
        时.textContent = 时刻(m.时间);
        条.appendChild(泡);
        条.appendChild(时);
        列表.appendChild(条);
      }
      if (发送中) {
        const 条 = document.createElement('div');
        条.className = `${前缀}__sms ${前缀}__sms--her`;
        const 泡 = document.createElement('div');
        泡.className = `${前缀}__bubble ${前缀}__bubble--wait`;
        泡.textContent = '……';
        条.appendChild(泡);
        列表.appendChild(条);
      }
      if (失败) {
        const 行 = document.createElement('div');
        行.className = `${前缀}__fail`;
        行.append('她没回消息。');
        const 重试 = document.createElement('button');
        重试.type = 'button';
        重试.className = `${前缀}__retry`;
        重试.textContent = '再发一次';
        重试.disabled = 发送中;
        重试.addEventListener('click', () => 重发());
        行.appendChild(重试);
        列表.appendChild(行);
      }
      输入.disabled = 发送中;
      发送钮.disabled = 发送中 || 输入.value.trim().length === 0;
      滚到底();
    }

    async function 求回信(玩家消息: string): Promise<void> {
      发送中 = true;
      失败 = false;
      渲染();
      await 写记录(记录);
      const 回 = await 请她回信(玩家消息, 记录);
      发送中 = false;
      if (回 === null) 失败 = true;
      else 记录 = [...记录, { 我方: false, 文: 回, 时间: Date.now() }];
      await 写记录(记录);
      渲染();
    }

    async function 发送(): Promise<void> {
      const 文 = 输入.value.trim();
      if (!文 || 发送中 || 对局中()) return;
      输入.value = '';
      记录 = [...记录, { 我方: true, 文, 时间: Date.now() }];
      渲染();
      await 求回信(文);
    }

    function 重发(): void {
      const 上一条 = [...记录].reverse().find(m => m.我方);
      if (!上一条 || 发送中) return;
      void 求回信(上一条.文);
    }

    function 开(): void {
      记录 = 读记录();
      窗口.classList.add(`${前缀}--open`);
      渲染();
      setTimeout(() => 输入.focus(), 30);
    }

    function 关(): void {
      窗口.classList.remove(`${前缀}--open`);
    }

    启动钮.addEventListener('click', () => (窗口.classList.contains(`${前缀}--open`) ? 关() : 开()));
    按钮.addEventListener('click', 关);
    发送钮.addEventListener('click', () => void 发送());
    输入.addEventListener('input', 渲染);
    输入.addEventListener('keydown', e => {
      if (e.key === 'Enter') void 发送();
    });

    console.info('[小手机] 已挂载');
  } catch (错误) {
    console.warn('[小手机] 挂载失败', 错误);
  }
});

$(window).on('pagehide', () => {
  document.getElementById(`${前缀}-launcher`)?.remove();
  document.getElementById(`${前缀}-win`)?.remove();
  document.getElementById(`${前缀}-style`)?.remove();
});
